<template><main class="zj-workspace"><header class="zj-heading"><div><div class="zj-eyebrow">众基消防 / 财务管理</div><h1>报账总览</h1><p>按日期、人员和项目核对费用，切换列表、卡片或分析视图。</p></div><el-radio-group v-model="view"><el-radio-button value="list">列表</el-radio-button><el-radio-button value="cards">卡片</el-radio-button><el-radio-button value="analysis">分析</el-radio-button></el-radio-group></header><section class="zj-card"><div class="zj-filters"><el-input v-model="q.name" placeholder="用途、报账人或提交凭据" clearable @keyup.enter="search"/><el-date-picker v-model="range" type="daterange" value-format="YYYY-MM-DD" start-placeholder="开始日期" end-placeholder="结束日期"/><el-select v-model="q.status" clearable placeholder="全部状态"><el-option label="待核验" value="pending"/><el-option label="已支付" value="paid"/><el-option label="不予报销" value="rejected"/></el-select><el-select v-model="q.source" clearable placeholder="全部来源"><el-option label="免登录手机" value="public"/><el-option label="后台录入" value="staff"/><el-option label="历史迁移" value="legacy"/></el-select><el-select v-model="q.userId" filterable clearable remote :remote-method="findUsers" placeholder="筛选报账人"><el-option v-for="u in users" :key="u.id" :value="u.id" :label="u.name"/></el-select><el-select v-model="q.projectId" filterable clearable remote :remote-method="findProjects" placeholder="筛选项目"><el-option v-for="p in projects" :key="p.id" :value="p.id" :label="p.name"/></el-select><el-button type="primary" @click="search">查询</el-button><el-button @click="reset">清空</el-button></div></section><el-alert v-if="error" title="加载失败，请重新查询" type="error" :closable="false"/><section class="metrics"><div v-for="m in metrics" :key="m.label" class="zj-card"><small>{{m.label}}</small><strong>{{m.value}}</strong></div></section><section v-loading="loading" class="zj-card"><el-table v-if="view==='list'" :data="rows" empty-text="暂无符合条件的报账"><el-table-column prop="expenseDate" label="日期" width="120"/><el-table-column prop="claimantName" label="报账人" width="120"/><el-table-column label="金额（元）" width="160" align="right"><template #default="{row}">{{money(row.amount)}}</template></el-table-column><el-table-column prop="purpose" label="用途" min-width="220"/><el-table-column label="项目" min-width="200"><template #default="{row}">{{row.projectName||'未关联项目'}}</template></el-table-column><el-table-column label="来源 / 状态" width="180"><template #default="{row}">{{sources[row.source]}}<br/><el-tag :type="row.status==='paid'?'success':row.status==='rejected'?'danger':'warning'">{{statuses[row.status]}}</el-tag></template></el-table-column><el-table-column label="操作" width="90"><template #default="{row}"><el-button link type="primary" @click="detail(row.id)">详情</el-button></template></el-table-column></el-table><div v-else-if="view==='cards'" class="expense-cards"><el-empty v-if="!rows.length" description="暂无报账"/><article v-for="r in rows" :key="r.id" @click="detail(r.id)"><strong>¥ {{money(r.amount)}}</strong><h3>{{r.claimantName||'历史人员待确认'}}</h3><p>{{r.purpose}}</p><small>{{r.expenseDate}} · {{r.projectName||'未关联项目'}}</small><p>{{sources[r.source]}} · {{statuses[r.status]}}</p><el-button link type="primary">查看详情</el-button></article></div><template v-else><h2>月度费用</h2><div v-for="m in analysis.months||[]" :key="m.label" class="month-row"><span>{{m.label||'日期待确认'}}</span><div><i :style="{width:bar(m.amount)+'%'}"/></div><strong>{{money(m.amount)}}</strong></div><el-empty v-if="!analysis.months?.length" description="暂无月度数据"/><el-radio-group v-model="breakdown"><el-radio-button value="people">按人员</el-radio-button><el-radio-button value="projects">按项目</el-radio-button></el-radio-group><el-table :data="analysis[breakdown]||[]"><el-table-column prop="label" :label="breakdown==='people'?'报账人':'项目'"/><el-table-column prop="records" label="笔数" width="100"/><el-table-column label="金额（元）" align="right" width="180"><template #default="{row}">{{money(row.amount)}}</template></el-table-column></el-table><p class="zj-sub">统计覆盖当前筛选条件下的全部记录，列表分页不影响合计。</p></template><el-pagination v-if="view!=='analysis'" v-model:current-page="q.pageNum" :page-size="20" :total="total" layout="total,prev,pager,next" @current-change="load"/></section><el-drawer v-model="open" title="报账详情" size="min(760px,96vw)"><template v-if="selected"><h2>¥ {{money(selected.amount)}}</h2><el-descriptions :column="1" border><el-descriptions-item label="用途">{{selected.purpose}}</el-descriptions-item><el-descriptions-item label="报账人">{{selected.claimantName}}</el-descriptions-item><el-descriptions-item label="日期">{{selected.expenseDate||'待确认'}}</el-descriptions-item><el-descriptions-item label="关联项目">{{selected.projectName||'未关联项目'}}</el-descriptions-item><el-descriptions-item label="来源">{{sources[selected.source]}} {{selected.source==='public'?'（填报人自行选择，需财务核实）':''}}</el-descriptions-item><el-descriptions-item label="录入账号">{{selected.createdBy}}</el-descriptions-item><el-descriptions-item label="备注">{{selected.remark||'无'}}</el-descriptions-item><el-descriptions-item label="提交凭据">{{selected.receipt}}</el-descriptions-item></el-descriptions><h3>发票 / 凭证</h3><el-link v-for="(f,i) in (selected.invoices||'').split(',').filter(Boolean)" :key="f" :href="fileUrl(f)" target="_blank" type="primary" style="display:block">查看凭证 {{i+1}}</el-link><el-empty v-if="!selected.invoices" description="未上传凭证"/><el-form label-position="top" v-if="canEdit"><el-form-item label="处理状态"><el-select v-model="selected.status"><el-option v-for="(label,status) in statuses" :key="status" :value="status" :label="label"/></el-select></el-form-item><el-button type="primary" :loading="saving" @click="saveStatus">保存状态</el-button></el-form><el-collapse v-if="selected.legacySnapshot"><el-collapse-item title="历史原始数据"><pre style="white-space:pre-wrap;overflow-wrap:anywhere">{{selected.legacySnapshot}}</pre></el-collapse-item></el-collapse></template></el-drawer></main></template>
<script setup>
import {expenseList,expenseDetail,expenseAnalysis,expenseStatus,expenseOptions,money} from '@/api/projectFinance';import {fileUrl} from '@/utils/files';import auth from '@/plugins/auth';import '@/assets/styles/zhongji.scss';
const {proxy}=getCurrentInstance(),view=ref('list'),breakdown=ref('people'),range=ref([]),q=reactive({name:'',status:'',source:'',projectId:null,userId:null,pageNum:1,pageSize:20}),rows=ref([]),total=ref(0),analysis=ref({summary:{}}),loading=ref(false),error=ref(false),users=ref([]),projects=ref([]),open=ref(false),selected=ref(),saving=ref(false);let seq=0;
const statuses={pending:'待核验',paid:'已支付',rejected:'不予报销'},sources={public:'免登录手机',staff:'后台录入',legacy:'历史迁移'},canEdit=computed(()=>auth.hasPermi('zhongji:finance:edit'));const metrics=computed(()=>[{label:'报账笔数',value:analysis.value.summary?.records||0},{label:'报账总额（元）',value:money(analysis.value.summary?.totalAmount)},{label:'待核验金额（元）',value:money(analysis.value.summary?.pendingAmount)},{label:'已支付金额（元）',value:money(analysis.value.summary?.paidAmount)}]);
async function load(){const n=++seq;loading.value=true;error.value=false;try{const params={...q,dateFrom:range.value?.[0]||'',dateTo:range.value?.[1]||''};const [l,a]=await Promise.all([expenseList(params),expenseAnalysis(params)]);if(n===seq){rows.value=l.rows;total.value=l.total;analysis.value=a.data}}catch{if(n===seq){rows.value=[];analysis.value={summary:{}};error.value=true}}finally{if(n===seq)loading.value=false}}
function search(){q.pageNum=1;load()}function reset(){Object.assign(q,{name:'',status:'',source:'',projectId:null,userId:null,pageNum:1});range.value=[];load()}async function findUsers(name){users.value=(await expenseOptions('users',name)).data}async function findProjects(name){projects.value=(await expenseOptions('projects',name)).data}
function bar(amount){return Math.max(1,Number(amount)/Math.max(1,...(analysis.value.months||[]).map(x=>Number(x.amount)))*100)}async function detail(id){selected.value=(await expenseDetail(id)).data;open.value=true}async function saveStatus(){saving.value=true;try{await expenseStatus(selected.value.id,{status:selected.value.status,version:selected.value.version});proxy.$modal.msgSuccess('状态已保存');await detail(selected.value.id);await load()}finally{saving.value=false}}onMounted(load);
</script><style scoped>.metrics{display:grid;grid-template-columns:repeat(4,1fr);gap:16px}.metrics small,.metrics strong{display:block}.metrics strong{font-size:24px;margin-top:12px}.expense-cards{display:grid;grid-template-columns:repeat(auto-fill,minmax(260px,1fr));gap:16px}.expense-cards article{border:1px solid #e5eaf2;border-radius:12px;padding:20px;cursor:pointer}.expense-cards article>strong{font-size:24px;color:#2458d3}.month-row{display:flex;align-items:center;gap:12px;margin:18px 0}.month-row>span{min-width:100px}.month-row>div{height:18px;background:#f4f6fa;flex:1;border-radius:6px;overflow:hidden}.month-row i{display:block;background:#2458d3;height:100%}.month-row strong{min-width:130px;text-align:right}@media(max-width:800px){.metrics{grid-template-columns:1fr 1fr}.metrics strong{font-size:20px}.month-row{flex-wrap:wrap}}</style>
